SELECT CASE WHEN discount_pct >= 0.34 THEN 'PREMIUM' ELSE 'STANDARD' END AS discount_pct_tier, channel, DATE_TRUNC('YEAR', ends_on) AS year_start, COUNT(CASE WHEN channel = 'partner' THEN 1 END) AS partner_count, COUNT(DISTINCT promo_code) AS distinct_promo_codes, COUNT(CASE WHEN promo_code = 'VIP' THEN 1 END) AS vip_count, STDDEV_SAMP(discount_pct) AS discount_pct_stddev, COUNT(*) AS cnt, COUNT(DISTINCT channel) AS distinct_channels FROM promotions GROUP BY ROLLUP (CASE WHEN discount_pct >= 0.34 THEN 'PREMIUM' ELSE 'STANDARD' END, channel, DATE_TRUNC('YEAR', ends_on)) ORDER BY year_start DESC;
